// JavaScript side: lib/mj.js on the vendored MuJoCo 3.14.0 WebAssembly build, same XML.
const TUMBLE_QPOS = [-0.15, 0.0, 0.25, 0.9537169507482269, 0.21263110997159387, 0.21263110997159387, 0.0];
const TUMBLE_QVEL = [0.4, 0.0, 0.0, 6.0, -6.0, 2.0];
const BAD_XML = "<mujoco><worldbody><body><joint type='bogus'/><geom size='0.1'/></body></worldbody></mujoco>";
const C = (s) => s.contacts().map((c) => ({ geom1: c.geom1, geom2: c.geom2, dist: c.dist, pos: c.pos,
  frame: c.frame, force: c.force, fworld: c.fworld }));
const run = async (name, fn) => { const s = await MJ.sim(MODELS[name]); try { return await fn(s); } finally { s.dispose(); } };
const boxDrop = (steps) => run("box_on_plane", (s) => { s.step(steps);
  return { time: s.time, qpos: Array.from(s.qpos), qvel: Array.from(s.qvel), ncon: s.ncon }; });
const boxRest = () => run("box_on_plane", (s) => { s.step(1500); return C(s); });
const tilted = (deg, cone, seconds = 1, mu = 0.5) => run("tilted_plane", (s) => {
  const th = (deg * Math.PI) / 180, q = [Math.cos(th / 2), 0, Math.sin(th / 2), 0];
  s.geomParam("ramp", { quat: q, friction: mu });
  s.setOpt({ cone });
  s.reset();
  s.qpos.set([0.025 * Math.sin(th), 0, 0.025 * Math.cos(th), q[0], q[1], q[2], q[3]]);
  s.qvel.fill(0);
  s.forward();
  const x0 = Array.from(s.qpos.subarray(0, 3)), down = [Math.cos(th), 0, -Math.sin(th)];
  s.step(Math.round(seconds / s.timestep));
  const slip = (s.qpos[0] - x0[0]) * down[0] + (s.qpos[1] - x0[1]) * down[1] + (s.qpos[2] - x0[2]) * down[2];
  return { slip, contacts: C(s) };
});
const tiltedAsLoaded = (steps = 500) => run("tilted_plane", (s) => {
  const x0 = Array.from(s.qpos.subarray(0, 3)), th = (20 * Math.PI) / 180;
  s.step(steps);
  return (s.qpos[0] - x0[0]) * Math.cos(th) - (s.qpos[2] - x0[2]) * Math.sin(th);
});
const tumbleInit = (s) => { s.qpos.set(TUMBLE_QPOS); s.qvel.set(TUMBLE_QVEL); s.forward(); };
const tumble = (steps) => run("box_on_plane", (s) => { tumbleInit(s); s.step(steps);
  return { qpos: Array.from(s.qpos), qvel: Array.from(s.qvel), ncon: s.ncon }; });
const pinch = (steps = 250) => run("two_finger_pinch", (s) => { s.reset("hold"); s.step(steps);
  return { box: s.body("box").xpos, pads: Array.from(s.qpos.subarray(0, 2)), contacts: C(s) }; });
const netOn = (cs, geoms) => cs.reduce((t, c) => {
  const sg = geoms.includes(c.geom2) ? 1 : geoms.includes(c.geom1) ? -1 : 0;
  return t.map((v, k) => v + sg * c.fworld[k]); }, [0, 0, 0]);
const uphill = (c) => -Math.cos(Math.PI / 9) * c.fworld[0] + Math.sin(Math.PI / 9) * c.fworld[2] > 0;
const sum = (xs) => xs.reduce((a, b) => a + b, 0);
const maxDiff = (a, b) => Math.max(...Array.from(a).map((v, i) => Math.abs(v - b[i])));
// Rollouts from a saved state: the same Sim, with and without the forward pass, and a second Sim.
const rollout = () => run("box_on_plane", async (s) => {
  const u = await MJ.sim(MODELS.box_on_plane);
  tumbleInit(s); s.step(120);
  const st = s.getState();
  const roll = (x) => { x.step(400); return Array.from(x.qpos).concat(Array.from(x.qvel), [x.time]); };
  const a = roll(s);
  s.setState(st, false); const b = roll(s);
  s.setState(st); const c = roll(s);
  u.setState(st, false); const d = roll(u);
  u.dispose();
  return [maxDiff(a, b), maxDiff(a, c), maxDiff(a, d)];
});
const badModelMessage = async () => {
  try { await MJ.sim(BAD_XML); return "compiled"; }
  catch (e) { return e.message.replace(/^MuJoCo Error: Loading error: /, "").trim(); }
};
